<?php
namespace OpenLMS\Controllers;

use OpenLMS\Core\Auth;
use OpenLMS\Core\Csrf;
use OpenLMS\Core\Database;
use OpenLMS\Policies\CoursePolicy;
use PDO;

trait AssessmentHelpersTrait
{
    private static function saveOptions(PDO $pdo,int $qid,string $text):void{$lines=preg_split('/\R+/',trim($text))?:[];$correct=0;$order=0;foreach($lines as $line){$line=trim($line);if($line==='')continue;$is=str_starts_with($line,'*');if($is){$line=ltrim(substr($line,1));$correct++;}$pdo->prepare('INSERT INTO question_options (question_id,option_text,is_correct,sort_order) VALUES (?,?,?,?)')->execute([$qid,mb_substr($line,0,1000),$is?1:0,++$order]);}if($order<2||$correct<1)throw new \RuntimeException('MCQ options need at least two choices and at least one correct option.');}
    private static function saveMatching(PDO $pdo,int $qid,string $text):void{$lines=preg_split('/\R+/',trim($text))?:[];$pairs=[];$order=0;foreach($lines as $line){if(!str_contains($line,'=>'))continue;[$left,$right]=array_map('trim',explode('=>',$line,2));if($left===''||$right==='')continue;$pairs[$left]=$right;$pdo->prepare('INSERT INTO question_options (question_id,option_text,is_correct,sort_order) VALUES (?,?,1,?)')->execute([$qid,$left.' => '.$right,++$order]);}if(count($pairs)<2)throw new \RuntimeException('Matching questions need at least two “left => right” pairs.');$pdo->prepare('UPDATE questions SET answer_text=? WHERE id=?')->execute([json_encode($pairs,JSON_UNESCAPED_UNICODE),$qid]);}
    private static function recalcQuiz(int $id):void{$pdo=Database::connection();$st=$pdo->prepare('SELECT COALESCE(SUM(q.marks),0) FROM quiz_questions qq JOIN questions q ON q.id=qq.question_id WHERE qq.quiz_id=?');$st->execute([$id]);$pdo->prepare('UPDATE quizzes SET total_marks=?,updated_at=? WHERE id=?')->execute([(float)$st->fetchColumn(),gmdate('Y-m-d H:i:s'),$id]);}
    private static function course(int $id):?array{$st=Database::connection()->prepare("SELECT c.*,s.status subject_status FROM courses c JOIN subjects s ON s.id=c.subject_id WHERE c.id=?");$st->execute([$id]);return $st->fetch()?:null;}
    private static function manageableCourses(array $u):array{$pdo=Database::connection();if(Auth::hasAnyRole(['super_admin','administrator','hod']))return $pdo->query("SELECT c.*,s.status subject_status FROM courses c JOIN subjects s ON s.id=c.subject_id WHERE c.status<>'archived' ORDER BY c.title")->fetchAll();$st=$pdo->prepare("SELECT c.*,s.status subject_status FROM courses c JOIN subjects s ON s.id=c.subject_id WHERE c.teacher_id=? AND c.status<>'archived' ORDER BY c.title");$st->execute([(int)$u['id']]);return $st->fetchAll();}
    private static function bank(int $id):?array{$st=Database::connection()->prepare('SELECT qb.*,c.teacher_id,c.title course_title FROM question_banks qb LEFT JOIN courses c ON c.id=qb.course_id WHERE qb.id=?');$st->execute([$id]);return $st->fetch()?:null;}
    private static function canManageBank(array $b,array $u):bool{return Auth::hasAnyRole(['super_admin','administrator','hod','examiner'])||(in_array('teacher',$u['roles'],true)&&(int)$b['teacher_id']===(int)$u['id']);}
    private static function banks(array $u):array{$pdo=Database::connection();$where=Auth::hasAnyRole(['super_admin','administrator','hod','examiner'])?'1=1':'c.teacher_id=?';$st=$pdo->prepare("SELECT qb.*,c.title course_title,(SELECT COUNT(*) FROM questions q WHERE q.question_bank_id=qb.id) question_count FROM question_banks qb LEFT JOIN courses c ON c.id=qb.course_id WHERE $where ORDER BY qb.id DESC");$st->execute($where==='1=1'?[]:[(int)$u['id']]);return $st->fetchAll();}
    private static function question(int $id):?array{$st=Database::connection()->prepare('SELECT q.*,qb.course_id,c.teacher_id FROM questions q JOIN question_banks qb ON qb.id=q.question_bank_id LEFT JOIN courses c ON c.id=qb.course_id WHERE q.id=?');$st->execute([$id]);return $st->fetch()?:null;}
    private static function quiz(int $id):?array{$st=Database::connection()->prepare('SELECT qz.*,c.teacher_id,c.status course_status,s.status subject_status,(SELECT COUNT(*) FROM quiz_questions qq WHERE qq.quiz_id=qz.id) question_count FROM quizzes qz JOIN courses c ON c.id=qz.course_id JOIN subjects s ON s.id=c.subject_id WHERE qz.id=?');$st->execute([$id]);return $st->fetch()?:null;}
    private static function canManageQuiz(array $q,array $u):bool{return Auth::hasAnyRole(['super_admin','administrator','hod','examiner'])||(in_array('teacher',$u['roles'],true)&&(int)$q['teacher_id']===(int)$u['id']);}
    private static function quizRows(array $u):array{$pdo=Database::connection();$where=Auth::hasAnyRole(['super_admin','administrator','hod','examiner'])?'1=1':'c.teacher_id=?';$st=$pdo->prepare("SELECT qz.*,c.title course_title,(SELECT COUNT(*) FROM quiz_questions qq WHERE qq.quiz_id=qz.id) question_count FROM quizzes qz JOIN courses c ON c.id=qz.course_id WHERE qz.assessment_type='quiz' AND $where ORDER BY qz.id DESC");$st->execute($where==='1=1'?[]:[(int)$u['id']]);return $st->fetchAll();}
}
